style.css:
@-moz-document domain("roblox.com") {
/* 1. Inject the Gothic Background */
    body, 
    .bg-main, 
    #container-main, 
    .main-layout {
        background-image: url('https://pinimg.com') !important;
        background-size: cover !important;
        background-position: center center !important;
        background-attachment: fixed !important;
        background-repeat: no-repeat !important;
        background-color: #000000 !important;
    }

    /* 2. Make Content Panels Semi-Transparent */
    .content, 
    .section-content, 
    .game-card-container, 
    .item-card-container,
    .avatar-card-container, 
    .roblox-popover-content,
    .dialog-container,
    .tab-content {
        background: rgba(15, 15, 15, 0.75) !important; /* Translucent dark tint */
        border: 1px solid #444444 !important;
        border-radius: 8px !important;
    }

    /* 3. Style the Navigation Side Bar */
    #navigation {
        background: rgba(10, 10, 10, 0.85) !important;
        border-right: 1px solid #333333 !important;
    }

    /* 4. Style the Top Header Bar */
    #header {
        background: rgba(5, 5, 5, 0.9) !important;
        border-bottom: 1px solid #333333 !important;
    }

    /* 5. Enhance Text Visibility */
    .text-title, .text-name, h1, h2, h3, .game-card-name, .item-card-name {
        color: #ffffff !important;
        text-shadow: 1px 1px 3px rgba(0, 0, 0, 0.9) !important;
    }
}
